#!/usr/bin/env bash
# After the GitHub release is published: take the AUR checksums from what GitHub actually serves, regenerate
# .SRCINFO, commit that to this repository and push PKGBUILD/.SRCINFO/.install to the AUR.
# GitHub release assets are not downloaded: the release API reports the sha256 GitHub computed on upload.
# Other sources (tag and commit archives, generated by GitHub on request) are downloaded and hashed.
# Pushes to origin and the AUR: run only when told to release.
# Usage: aur-publish.sh <tag>
set -euo pipefail
TAG=${1:?usage: aur-publish.sh <tag>}
REPO=$(git -C "$(dirname "$0")" rev-parse --show-toplevel)
A=$REPO/aur/waydroid-a17-nvidia-bin
grep -qx "_tag=$TAG" "$A/PKGBUILD" || { echo "aur-publish: PKGBUILD is not at $TAG" >&2; exit 1; }
[ "$(gh release view "$TAG" --json isDraft -q .isDraft)" = false ] ||
    { echo "aur-publish: release $TAG is still a draft" >&2; exit 1; }
T=$(mktemp -d)
trap 'rm -rf "$T"' EXIT

mapfile -t SOURCES < <(cd "$A" && bash -c 'source ./PKGBUILD && printf "%s\n" "${source[@]}"')
re='^https://github\.com/([^/]+/[^/]+)/releases/download/([^/]+)/([^/]+)$'
sums=()
for s in "${SOURCES[@]}"; do
    url=${s#*::}
    sum=
    if [[ $url =~ $re ]]; then
        rel=$T/rel-${BASH_REMATCH[1]//\//_}-${BASH_REMATCH[2]}.json
        [ -f "$rel" ] || gh api "repos/${BASH_REMATCH[1]}/releases/tags/${BASH_REMATCH[2]}" > "$rel"
        sum=$(jq -r --arg n "${BASH_REMATCH[3]}" \
            '.assets[] | select(.name == $n and .state == "uploaded") | .digest // empty' "$rel")
        sum=${sum#sha256:}
    fi
    if [ -z "$sum" ]; then
        # assets uploaded before GitHub recorded digests, and archives: download (TLS EOFs happen, retry)
        curl -fsSL --retry 5 --retry-all-errors -o "$T/dl" "$url"
        sum=$(sha256sum "$T/dl" | cut -d' ' -f1)
        rm -f "$T/dl"
    fi
    [[ $sum =~ ^[0-9a-f]{64}$ ]] || { echo "aur-publish: no sha256 for $url" >&2; exit 1; }
    echo "$sum  $url"
    sums+=("$sum")
done

{
    awk '/^sha256sums=\(/ { skip = 1 } !skip { print } skip && /\)[[:space:]]*$/ { exit }' "$A/PKGBUILD"
    for i in "${!sums[@]}"; do
        if [ "$i" = 0 ]; then p="sha256sums=("; else p="            "; fi
        if [ "$i" = $((${#sums[@]} - 1)) ]; then e=")"; else e=""; fi
        echo "$p'${sums[$i]}'$e"
    done
    awk 'done { print } /^sha256sums=\(/ { skip = 1 } skip && /\)[[:space:]]*$/ { skip = 0; done = 1 }' "$A/PKGBUILD"
} > "$T/PKGBUILD"
cp "$T/PKGBUILD" "$A/PKGBUILD"
(cd "$A" && makepkg --printsrcinfo > .SRCINFO)

cd "$REPO"
git add aur/waydroid-a17-nvidia-bin/PKGBUILD aur/waydroid-a17-nvidia-bin/.SRCINFO
git diff --cached --quiet || git commit -qm "AUR：$TAG 的校验和与 .SRCINFO"
git push -q origin HEAD
git clone -q ssh://aur@aur.archlinux.org/waydroid-a17-nvidia-bin.git "$T/aur"
cp "$A/PKGBUILD" "$A/.SRCINFO" "$A/waydroid-a17-nvidia.install" "$T/aur/"
cd "$T/aur"
git add -A
git diff --cached --quiet && { echo "aur-publish: AUR already at $TAG"; exit 0; }
git commit -qm "更新到 $TAG"
git push -q origin master
git log --oneline -1
